#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the argument as a decimal integer */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: no digits or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Accept only numbers in the range 1 … 1 000 000 */
    if (n < 1 || n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Compute the sum of proper divisors of n */
    long sum = 0;
    for (long i = 1; i < n; ++i) {
        if (n % i == 0)
            sum += i;
    }

    /* Classify the number */
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }

    return 0;
}
